seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
minus=rc(seq)
stop={'TAA','TAG','TGA'}

def up_free(s,f,p):
    # length of stop-free stretch in frame f immediately upstream of position p
    i=p-3
    while i>=0:
        if s[i:i+3] in stop: return p-(i+3)
        i-=3
    return p

def dn_free(s,f,p):
    # from first codon boundary start >= p in frame f
    start = p + ((f-p)%3)
    i=start
    while i+3<=len(s):
        if s[i:i+3] in stop: return i-p
        i+=3
    return len(s)-p

